    { const char * tb_v364 = "// Программа сама себе ОС: загружается через multiboot (QEMU, GRUB), пишет на экран\n"; *(const char * *)tb_grow(v_lines) = tb_v364; }
    { const char * tb_v365 = "// (текстовый режим VGA) и в последовательный порт COM1, память берёт из своего запаса.\n"; *(const char * *)tb_grow(v_lines) = tb_v365; }
    { const char * tb_v366 = "// Есть прерывания, таймер, клавиатура, задачи (background) и страницы памяти; файлов нет.\n"; *(const char * *)tb_grow(v_lines) = tb_v366; }
    { const char * tb_v367 = "#include <stddef.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v367; }
