    { const char * tb_v370 = "// «переменные потока» лежат подряд в своём разделе: при смене задачи он копируется целиком\n"; *(const char * *)tb_grow(v_lines) = tb_v370; }
    { const char * tb_v371 = "#define _Thread_local __attribute__((section(\".tbtls\")))\n"; *(const char * *)tb_grow(v_lines) = tb_v371; }
    { const char * tb_v372 = "#define EOF (-1)\n"; *(const char * *)tb_grow(v_lines) = tb_v372; }
    { const char * tb_v373 = "typedef struct tb_file FILE;\n"; *(const char * *)tb_grow(v_lines) = tb_v373; }
