    { const char * tb_v375 = "#define stderr ((FILE *)2)\n"; *(const char * *)tb_grow(v_lines) = tb_v375; }
    { const char * tb_v376 = "typedef long pthread_t;   // 8 байт, как адрес: раскладка задачи та же, что в обычной программе\n"; *(const char * *)tb_grow(v_lines) = tb_v376; }
    { const char * tb_v377 = "typedef int pthread_mutex_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v377; }
    { const char * tb_v378 = "#define PTHREAD_MUTEX_INITIALIZER 0\n"; *(const char * *)tb_grow(v_lines) = tb_v378; }
