    { const char * tb_v389 = "// выключить прерывания на время короткого дела и вернуть, как было\n"; *(const char * *)tb_grow(v_lines) = tb_v389; }
    { const char * tb_v390 = "TB_INL uint64_t tb_irq_save(void) { uint64_t f; __asm__ volatile(\"pushfq\\npopq %0\\ncli\" : \"=r\"(f) : : \"memory\"); return f; }\n"; *(const char * *)tb_grow(v_lines) = tb_v390; }
