    { const char * tb_v397 = "TB_API void tb_vga_put(unsigned char ch) {\n"; *(const char * *)tb_grow(v_lines) = tb_v397; }
    { const char * tb_v398 = "    if (ch == '\\n') { tb_vcol = 0; tb_vrow++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v398; }
    { const char * tb_v399 = "    else if (ch == '\\b') { if (tb_vcol > 0) tb_vcol--; tb_vga[tb_vrow * 80 + tb_vcol] = (unsigned short)(tb_vcolor << 8 | ' '); }\n"; *(const char * *)tb_grow(v_lines) = tb_v399; }
    { const char * tb_v400 = "    else {\n"; *(const char * *)tb_grow(v_lines) = tb_v400; }
