    { const char * tb_v2216 = "    long long need = *rl + lb + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2216; }
    { const char * tb_v2217 = "    if (need > *rc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2217; }
