    { const char * tb_v2655 = "// текст → строка JSON в кавычках: \"a\\\"b\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2655; }
    { const char * tb_v2656 = "TB_API const char *tb_json_text(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2656; }
    { const char * tb_v2657 = "    size_t n = strlen(s);\n"; *(const char * *)tb_grow(v_lines) = tb_v2657; }
    { const char * tb_v2658 = "    char *out = tb_tmem(n * 6 + 3), *o = out;\n"; *(const char * *)tb_grow(v_lines) = tb_v2658; }
