    { const char * tb_v2687 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2687; }
    { const char * tb_v2688 = "// случайное целое от a до b (оба входят)\n"; *(const char * *)tb_grow(v_lines) = tb_v2688; }
    { const char * tb_v2689 = "TB_API long long tb_random(long long a, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2689; }
    { const char * tb_v2690 = "    if (tb_rand_state == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2690; }
    { const char * tb_v2691 = "        struct timespec ts; clock_gettime(CLOCK_REALTIME, &ts);\n"; *(const char * *)tb_grow(v_lines) = tb_v2691; }
    { const char * tb_v2692 = "        tb_rand_state = ((unsigned long long)ts.tv_nsec << 20) ^ (unsigned long long)ts.tv_sec ^ 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2692; }
    { const char * tb_v2693 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2693; }
    { const char * tb_v2694 = "    if (b < a) { long long t = a; a = b; b = t; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2694; }
    { const char * tb_v2695 = "    tb_rand_state ^= tb_rand_state << 13; tb_rand_state ^= tb_rand_state >> 7; tb_rand_state ^= tb_rand_state << 17;\n"; *(const char * *)tb_grow(v_lines) = tb_v2695; }
