    { const char * tb_v2724 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2724; }
    { const char * tb_v2725 = "// ---------- dict: ключи и значения лежат в двух списках по порядку добавления,\n"; *(const char * *)tb_grow(v_lines) = tb_v2725; }
    { const char * tb_v2726 = "// а найти номер по ключу можно тремя способами (mode):\n"; *(const char * *)tb_grow(v_lines) = tb_v2726; }
    { const char * tb_v2727 = "//   1 — «номер = адрес»: ключи int шли подряд base, base+1, base+2 ... — номер = ключ - base, без поиска;\n"; *(const char * *)tb_grow(v_lines) = tb_v2727; }
    { const char * tb_v2728 = "//   2 — «адресное хранение»: ключи int лежат плотно — pos[ключ - base] = номер + 1, один взгляд;\n"; *(const char * *)tb_grow(v_lines) = tb_v2728; }
    { const char * tb_v2729 = "//   0 — таблица slots с хешем (текст или разбросанные числа) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2729; }
    { const char * tb_v2730 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v2730; }
    { const char * tb_v2731 = "    tb_list *keys; tb_list *vals; long long *slots; long long nslots; int text;\n"; *(const char * *)tb_grow(v_lines) = tb_v2731; }
    { const char * tb_v2732 = "    int mode; long long base; long long *pos; long long npos;\n"; *(const char * *)tb_grow(v_lines) = tb_v2732; }
    { const char * tb_v2733 = "} tb_dict;\n"; *(const char * *)tb_grow(v_lines) = tb_v2733; }
    { const char * tb_v2734 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2734; }
    { const char * tb_v2735 = "// ячейка таблицы: номер ключа + 1 (младшие 40 бит) и метка из старших битов хеша\n"; *(const char * *)tb_grow(v_lines) = tb_v2735; }
    { const char * tb_v2736 = "#define TB_DAT ((1LL << 40) - 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v2736; }
    { const char * tb_v2737 = "#define TB_DTAG(h) ((long long)(((h) >> 40) << 40) & ~TB_DAT & 0x7FFFFFFFFFFFFFFFLL)\n"; *(const char * *)tb_grow(v_lines) = tb_v2737; }
    { const char * tb_v2738 = "TB_API unsigned long long tb_hash(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2738; }
    { const char * tb_v2739 = "    unsigned long long h = 1469598103934665603ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2739; }
    { const char * tb_v2740 = "    if (d->text) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2740; }
    { const char * tb_v2741 = "        for (const unsigned char *p = *(const unsigned char * const *)k; *p; p++) { h ^= *p; h *= 1099511628211ULL; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2741; }
    { const char * tb_v2742 = "    } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v2742; }
    { const char * tb_v2743 = "        h ^= (unsigned long long)*(const long long *)k;\n"; *(const char * *)tb_grow(v_lines) = tb_v2743; }
    { const char * tb_v2744 = "        h *= 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2744; }
    { const char * tb_v2745 = "        h ^= h >> 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v2745; }
    { const char * tb_v2746 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2746; }
    { const char * tb_v2747 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v2747; }
    { const char * tb_v2748 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2748; }
    { const char * tb_v2749 = "TB_API int tb_keq(tb_dict *d, const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2749; }
    { const char * tb_v2750 = "    if (d->text) return strcmp(*(const char * const *)a, *(const char * const *)b) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2750; }
    { const char * tb_v2751 = "    return *(const long long *)a == *(const long long *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v2751; }
    { const char * tb_v2752 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2752; }
    { const char * tb_v2753 = "TB_INL long long tb_dfind(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2753; }
    { const char * tb_v2754 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2754; }
    { const char * tb_v2755 = "        unsigned long long at = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v2755; }
    { const char * tb_v2756 = "        return at < (unsigned long long)d->keys->len ? (long long)at : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2756; }
    { const char * tb_v2757 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2757; }
    { const char * tb_v2758 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2758; }
    { const char * tb_v2759 = "        unsigned long long o = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v2759; }
    { const char * tb_v2760 = "        return o < (unsigned long long)d->npos ? d->pos[o] - 1 : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2760; }
    { const char * tb_v2761 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2761; }
    { const char * tb_v2762 = "    unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2762; }
    { const char * tb_v2763 = "    long long tag = TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v2763; }
    { const char * tb_v2764 = "    while (d->slots[i] != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2764; }
    { const char * tb_v2765 = "        long long sl = d->slots[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2765; }
