    { const char * tb_v3095 = "// чтение и запись по адресу: volatile — компилятор C не выкинет и не переставит их\n"; *(const char * *)tb_grow(v_lines) = tb_v3095; }
    { const char * tb_v3096 = "// shared x += n без замка. В ядре без ОС одно ядро процессора: хватает выключить прерывания\n"; *(const char * *)tb_grow(v_lines) = tb_v3096; }
