    { const char * tb_v3151 = "    long long n = 0, bytes = 0; int first = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3151; }
    { const char * tb_v3152 = "    for (long long i = 0; i < tb_mem_n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3152; }
    { const char * tb_v3153 = "        if (tb_mem_all[i].live) { if (!n) first = tb_mem_all[i].line; n++; bytes += (long long)tb_mem_all[i].n; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3153; }
    { const char * tb_v3154 = "    if (n && tb_mem_check) fprintf(stderr, \"TB_MEM_CHECK: не освобождено блоков %lld (%lld байт), первый из new_mem в строке %d\\n\", n, bytes, first);\n"; *(const char * *)tb_grow(v_lines) = tb_v3154; }
    { const char * tb_v3155 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3155; }
    { const char * tb_v3156 = "// TB_MEM_CHECK: можно ли трогать байты [a, a + n)\n"; *(const char * *)tb_grow(v_lines) = tb_v3156; }
    { const char * tb_v3157 = "static void tb_mem_touch(uintptr_t a, uint64_t n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3157; }
    { const char * tb_v3158 = "    if (n == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3158; }
    { const char * tb_v3159 = "    tb_mem_lock();\n"; *(const char * *)tb_grow(v_lines) = tb_v3159; }
    { const char * tb_v3160 = "    for (long long i = 0; i < tb_mem_n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3160; }
