    { const char * tb_v3162 = "        uintptr_t lo = b->a - sizeof(tb_memh), hi = b->a + b->n + TB_MEM_GUARD;\n"; *(const char * *)tb_grow(v_lines) = tb_v3162; }
    { const char * tb_v3163 = "        if (a + n <= lo || a >= hi) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v3163; }
    { const char * tb_v3164 = "        if (!b->live) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3164; }
    { const char * tb_v3165 = "            char buf[160];\n"; *(const char * *)tb_grow(v_lines) = tb_v3165; }
    { const char * tb_v3166 = "            snprintf(buf, sizeof buf, \"эта память уже освобождена: free_mem в строке %d\", b->fline);\n"; *(const char * *)tb_grow(v_lines) = tb_v3166; }
    { const char * tb_v3167 = "            tb_mem_die(line, buf, b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3167; }
    { const char * tb_v3168 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3168; }
    { const char * tb_v3169 = "        if (a < b->a || a + n > b->a + b->n) tb_mem_die(line, \"чтение или запись за краем блока\", b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3169; }
    { const char * tb_v3170 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3170; }
    { const char * tb_v3171 = "    tb_mem_unlock();\n"; *(const char * *)tb_grow(v_lines) = tb_v3171; }
    { const char * tb_v3172 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3172; }
    { const char * tb_v3173 = "static tb_memb *tb_mem_find(uintptr_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3173; }
    { const char * tb_v3174 = "    for (long long i = tb_mem_n - 1; i >= 0; i--) if (tb_mem_all[i].a == a) return &tb_mem_all[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v3174; }
    { const char * tb_v3175 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3175; }
    { const char * tb_v3176 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3176; }
    { const char * tb_v3177 = "// чтение и запись по адресу: volatile — компилятор C не выкинет и не переставит их\n"; *(const char * *)tb_grow(v_lines) = tb_v3177; }
    { const char * tb_v3178 = "#define TB_TOUCH(a, n) if (TB_RARE(tb_memchk())) tb_mem_touch((uintptr_t)(a), (n), line)\n"; *(const char * *)tb_grow(v_lines) = tb_v3178; }
    { const char * tb_v3179 = "TB_INL long long tb_rd8(long long a, int line) { TB_TOUCH(a, 1); return *(volatile uint8_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3179; }
