    { const char * tb_v3188 = "// new_mem(байт): новый блок, заполнен нулями; адрес — число. Может не получиться (нет памяти)\n"; *(const char * *)tb_grow(v_lines) = tb_v3188; }
    { const char * tb_v3189 = "TB_API long long tb_new_mem(long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3189; }
    { const char * tb_v3190 = "    if (n <= 0) { tb_err = \"new_mem: размер должен быть больше нуля\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3190; }
    { const char * tb_v3191 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"new_mem: слишком большой блок\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3191; }
