    { const char * tb_v3213 = "// проверить адрес для free_mem / grow_mem; вернуть заголовок блока\n"; *(const char * *)tb_grow(v_lines) = tb_v3213; }
    { const char * tb_v3214 = "static tb_memh *tb_mem_own(long long a, int line, const char *who) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3214; }
    { const char * tb_v3215 = "    char buf[120];\n"; *(const char * *)tb_grow(v_lines) = tb_v3215; }
    { const char * tb_v3216 = "    if (tb_memchk()) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3216; }
    { const char * tb_v3217 = "        tb_mem_lock();\n"; *(const char * *)tb_grow(v_lines) = tb_v3217; }
    { const char * tb_v3218 = "        tb_memb *b = tb_mem_find((uintptr_t)a);\n"; *(const char * *)tb_grow(v_lines) = tb_v3218; }
    { const char * tb_v3219 = "        if (!b) { snprintf(buf, sizeof buf, \"%s: это не адрес из new_mem\", who); tb_mem_die(line, buf, 0); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3219; }
    { const char * tb_v3220 = "        if (!b->live) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3220; }
    { const char * tb_v3221 = "            snprintf(buf, sizeof buf, \"%s: блок уже освобождён в строке %d\", who, b->fline);\n"; *(const char * *)tb_grow(v_lines) = tb_v3221; }
    { const char * tb_v3222 = "            tb_mem_die(line, buf, b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3222; }
    { const char * tb_v3223 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3223; }
    { const char * tb_v3224 = "        const unsigned char *g = (const unsigned char *)(uintptr_t)a + b->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v3224; }
    { const char * tb_v3225 = "        for (int i = 0; i < TB_MEM_GUARD; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3225; }
    { const char * tb_v3226 = "            if (g[i] != 0xFB) tb_mem_die(line, \"кто-то писал за краем блока\", b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3226; }
    { const char * tb_v3227 = "        tb_mem_unlock();\n"; *(const char * *)tb_grow(v_lines) = tb_v3227; }
