    { const char * tb_v3230 = "    tb_memh *h = (tb_memh *)(uintptr_t)a - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3230; }
    { const char * tb_v3231 = "    if (h->magic == TB_MEM_DEAD) { snprintf(buf, sizeof buf, \"%s: блок уже освобождён\", who); tb_crash(line, buf); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3231; }
    { const char * tb_v3232 = "    if (h->magic != TB_MEM_LIVE) { snprintf(buf, sizeof buf, \"%s: это не адрес из new_mem или блок уже освобождён (точнее покажет TB_MEM_CHECK=1)\", who); tb_crash(line, buf); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3232; }
    { const char * tb_v3233 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v3233; }
    { const char * tb_v3234 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3234; }
    { const char * tb_v3235 = "// TB_MEM_CHECK: блок не отдаётся обратно, а помечается — чтобы поймать чтение после free_mem\n"; *(const char * *)tb_grow(v_lines) = tb_v3235; }
    { const char * tb_v3236 = "static void tb_mem_bury(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3236; }
    { const char * tb_v3237 = "    tb_mem_lock();\n"; *(const char * *)tb_grow(v_lines) = tb_v3237; }
