    { const char * tb_v3243 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3243; }
    { const char * tb_v3244 = "// free_mem(адрес): отдать блок; free_mem(0) ничего не делает\n"; *(const char * *)tb_grow(v_lines) = tb_v3244; }
    { const char * tb_v3245 = "TB_API void tb_free_mem(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3245; }
    { const char * tb_v3246 = "    if (a == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3246; }
