    { const char * tb_v3454 = "        if (x < 0 || (bn < 63 && (x >> bn))) tb_crash(line, \"число не влезает в поле bits: от 0 до 2 в степени N без единицы\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3454; }
    { const char * tb_v3455 = "        uint64_t m = bn < 64 ? (((uint64_t)1 << bn) - 1) << bo : ~(uint64_t)0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3455; }
    { const char * tb_v3456 = "        uint64_t v = tb_shape_raw(p, nb);\n"; *(const char * *)tb_grow(v_lines) = tb_v3456; }
    { const char * tb_v3457 = "        if (k & 32) v = tb_shape_swap(v, nb);\n"; *(const char * *)tb_grow(v_lines) = tb_v3457; }
    { const char * tb_v3458 = "        v = (v & ~m) | (((uint64_t)x << bo) & m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3458; }
    { const char * tb_v3459 = "        if (k & 32) v = tb_shape_swap(v, nb);\n"; *(const char * *)tb_grow(v_lines) = tb_v3459; }
