    { const char * tb_v3785 = "TB_API int tb_cursor_want = 0;                 // курсор, который просили до window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v3785; }
    { const char * tb_v3786 = "TB_API void tb_type_cp(unsigned u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3786; }
    { const char * tb_v3787 = "    if (u < 32 || u == 127 || (u >= 0xF700 && u <= 0xF8FF) || u > 0x10FFFF) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3787; }
    { const char * tb_v3788 = "    if (tb_ntyped + 4 >= (int)sizeof tb_typed) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3788; }
