    { const char * tb_v3855 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3855; }
    { const char * tb_v3856 = "    z->err = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3856; }
