    { const char * tb_v4047 = "static unsigned tb_u16(const tb_font_t *f, size_t o) { return o + 2 <= f->n ? (unsigned)(f->d[o] << 8 | f->d[o + 1]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4047; }
    { const char * tb_v4048 = "static int tb_s16(const tb_font_t *f, size_t o) { return (int16_t)tb_u16(f, o); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4048; }
    { const char * tb_v4049 = "static uint32_t tb_u32(const tb_font_t *f, size_t o) { return o + 4 <= f->n ? ((uint32_t)f->d[o] << 24 | (uint32_t)f->d[o + 1] << 16 | (uint32_t)f->d[o + 2] << 8 | f->d[o + 3]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4049; }
    { const char * tb_v4050 = "static uint32_t tb_ttf_table(const tb_font_t *f, size_t base, const char *tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4050; }
