    { const char * tb_v4144 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4144; }
    { const char * tb_v4145 = "static void tb_quad(tb_edges *E, double x0, double y0, double cx, double cy, double x1, double y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4145; }
