    { const char * tb_v4327 = "    tb_image *list = realloc(tb_imgs, (size_t)(tb_nimg + 1) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v4327; }
    { const char * tb_v4328 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v4328; }
    { const char * tb_v4329 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v4329; }
    { const char * tb_v4330 = "    if (!all || !list) { free(acc); return c; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4330; }
    { const char * tb_v4331 = "    uint32_t *px = tb_imgpx + tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4331; }
    { const char * tb_v4332 = "    for (int j = 0; j < h; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4332; }
    { const char * tb_v4333 = "        float sum = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4333; }
    { const char * tb_v4334 = "        const float *row = acc + (size_t)j * (w + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v4334; }
    { const char * tb_v4335 = "        for (int i = 0; i < w; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4335; }
    { const char * tb_v4336 = "            sum += row[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v4336; }
    { const char * tb_v4337 = "            float a = sum < 0 ? -sum : sum;\n"; *(const char * *)tb_grow(v_lines) = tb_v4337; }
