    { const char * tb_v4339 = "            px[j * w + i] = ((uint32_t)ai << 24) | (color & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v4339; }
    { const char * tb_v4340 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4340; }
    { const char * tb_v4341 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4341; }
    { const char * tb_v4342 = "    free(acc);\n"; *(const char * *)tb_grow(v_lines) = tb_v4342; }
    { const char * tb_v4343 = "    tb_imgs[tb_nimg].w = w; tb_imgs[tb_nimg].h = h; tb_imgs[tb_nimg].off = (uint32_t)tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4343; }
    { const char * tb_v4344 = "    tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v4344; }
    { const char * tb_v4345 = "    tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4345; }
    { const char * tb_v4346 = "    c->img = tb_nimg++; c->left = left; c->top = top;\n"; *(const char * *)tb_grow(v_lines) = tb_v4346; }
    { const char * tb_v4347 = "    return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v4347; }
    { const char * tb_v4348 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4348; }
    { const char * tb_v4349 = "// высота строки — size * 5 / 4; линия букв — так, чтобы верх и низ шрифта легли в эту строку\n"; *(const char * *)tb_grow(v_lines) = tb_v4349; }
    { const char * tb_v4350 = "static int tb_font_base(const tb_font_t *f, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4350; }
    { const char * tb_v4351 = "    double lh = size * 5 / 4.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4351; }
    { const char * tb_v4352 = "    return (int)floor(lh * f->asc / (f->asc - f->desc) + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v4352; }
    { const char * tb_v4353 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4353; }
    { const char * tb_v4354 = "static unsigned tb_utf8_next(const unsigned char **pp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4354; }
    { const char * tb_v4355 = "    const unsigned char *p = *pp;\n"; *(const char * *)tb_grow(v_lines) = tb_v4355; }
    { const char * tb_v4356 = "    unsigned u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4356; }
    { const char * tb_v4357 = "    if (u >= 0x80) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4357; }
    { const char * tb_v4358 = "        int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4358; }
    { const char * tb_v4359 = "        u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v4359; }
    { const char * tb_v4360 = "        while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v4360; }
    { const char * tb_v4361 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4361; }
    { const char * tb_v4362 = "    *pp = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v4362; }
    { const char * tb_v4363 = "    return u;\n"; *(const char * *)tb_grow(v_lines) = tb_v4363; }
    { const char * tb_v4364 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4364; }
    { const char * tb_v4365 = "TB_API long long tb_text_width(long long fi, const char *s, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4365; }
    { const char * tb_v4366 = "    if (fi < 0 || fi >= tb_nfonts || size <= 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4366; }
    { const char * tb_v4367 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v4367; }
    { const char * tb_v4368 = "    double scale = (double)size / f->upem, pen = 0, best = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4368; }
    { const char * tb_v4369 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v4369; }
    { const char * tb_v4370 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4370; }
    { const char * tb_v4371 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v4371; }
    { const char * tb_v4372 = "        if (u == '\\n') { if (pen > best) best = pen; pen = 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4372; }
    { const char * tb_v4373 = "        pen += tb_ttf_adv(f, tb_ttf_glyph(f, u)) * scale;\n"; *(const char * *)tb_grow(v_lines) = tb_v4373; }
    { const char * tb_v4374 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4374; }
    { const char * tb_v4375 = "    if (pen > best) best = pen;\n"; *(const char * *)tb_grow(v_lines) = tb_v4375; }
    { const char * tb_v4376 = "    return (long long)floor(best + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v4376; }
    { const char * tb_v4377 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4377; }
    { const char * tb_v4378 = "TB_API void tb_draw_image_a(long long id, long long x, long long y);\n"; *(const char * *)tb_grow(v_lines) = tb_v4378; }
    { const char * tb_v4379 = "TB_API void tb_draw_font(long long fi, long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4379; }
    { const char * tb_v4380 = "    if (!tb_px || fi < 0 || fi >= tb_nfonts || size <= 0 || size > 1000) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4380; }
    { const char * tb_v4381 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v4381; }
    { const char * tb_v4382 = "    double scale = (double)size / f->upem, pen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4382; }
    { const char * tb_v4383 = "    long long base = y + tb_font_base(f, size), lh = size * 5 / 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v4383; }
    { const char * tb_v4384 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v4384; }
    { const char * tb_v4385 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4385; }
    { const char * tb_v4386 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v4386; }
    { const char * tb_v4387 = "        if (u == '\\n') { pen = 0; base += lh; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4387; }
    { const char * tb_v4388 = "        unsigned g = tb_ttf_glyph(f, u);\n"; *(const char * *)tb_grow(v_lines) = tb_v4388; }
    { const char * tb_v4389 = "        long long gx = x + (long long)floor(pen + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v4389; }
    { const char * tb_v4390 = "        pen += tb_ttf_adv(f, g) * scale;\n"; *(const char * *)tb_grow(v_lines) = tb_v4390; }
    { const char * tb_v4391 = "        if (u == ' ' || gx >= tb_gw || base - 2 * size > tb_gh) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v4391; }
    { const char * tb_v4392 = "        tb_gcache *gc = tb_glyph_img((int)fi, g, (int)size, (uint32_t)c & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v4392; }
    { const char * tb_v4393 = "        if (gc->img >= 0) tb_draw_image_a(gc->img, gx + gc->left, base + gc->top);\n"; *(const char * *)tb_grow(v_lines) = tb_v4393; }
    { const char * tb_v4394 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4394; }
    { const char * tb_v4395 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4395; }
    { const char * tb_v4396 = "// ---------- рисование на видеокарте (GPU) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4396; }
    { const char * tb_v4397 = "// Кадр не рисуется точками на процессоре: каждая фигура записывается как «экземпляр»\n"; *(const char * *)tb_grow(v_lines) = tb_v4397; }
    { const char * tb_v4398 = "// (прямоугольник, круг или буква), а видеокарта рисует их все разом — по тем же правилам\n"; *(const char * *)tb_grow(v_lines) = tb_v4398; }
    { const char * tb_v4399 = "// точек, что и процессор (tb_draw_* ниже). Mac — Metal, Linux и Windows — Vulkan.\n"; *(const char * *)tb_grow(v_lines) = tb_v4399; }
    { const char * tb_v4400 = "// Если видеокарты нет (нет драйвера Vulkan, нет экрана) — рисуем как раньше, на процессоре.\n"; *(const char * *)tb_grow(v_lines) = tb_v4400; }
    { const char * tb_v4401 = "//   TB_GPU=0        — всегда на процессоре\n"; *(const char * *)tb_grow(v_lines) = tb_v4401; }
    { const char * tb_v4402 = "//   TB_GPU_CHECK=1  — рисовать и там и там и сверять каждый кадр точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v4402; }
    { const char * tb_v4403 = "//   TB_GPU_INFO=1   — сказать, чем рисуем\n"; *(const char * *)tb_grow(v_lines) = tb_v4403; }
    { const char * tb_v4404 = "typedef struct { int32_t x0, y0, x1, y1, ox, oy; uint32_t c, m; } tb_ginst;   // 32 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v4404; }
    { const char * tb_v4405 = "enum { TB_GI_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4405; }
    { const char * tb_v4406 = "TB_API int tb_gpu_on = 0, tb_gpu_check = 0, tb_gpu_first = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4406; }
    { const char * tb_v4407 = "TB_API tb_ginst *tb_gi = 0;            // память экземпляров (видна видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v4407; }
    { const char * tb_v4408 = "TB_API int tb_gin = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4408; }
    { const char * tb_v4409 = "// 3D: глубина. У треугольника сетки своя «плоскость глубины» A, B, C (целые числа, см. tb_tri3_depth);\n"; *(const char * *)tb_grow(v_lines) = tb_v4409; }
    { const char * tb_v4410 = "// она лежит в tb_gplane[набор * TB_GI_CAP + номер фигуры], а в m — 2 | (это место << 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v4410; }
    { const char * tb_v4411 = "typedef struct { uint32_t a, b, c, pad; } tb_gplane_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v4411; }
    { const char * tb_v4412 = "TB_API tb_gplane_t *tb_gplane = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4412; }
    { const char * tb_v4413 = "TB_API int tb_gzclr = 1;               // видеокарта: в начале кадра стереть глубину\n"; *(const char * *)tb_grow(v_lines) = tb_v4413; }
    { const char * tb_v4414 = "TB_API int tb_zclr = 1;                // процессор: то же для tb_zb\n"; *(const char * *)tb_grow(v_lines) = tb_v4414; }
    { const char * tb_v4415 = "TB_API uint32_t *tb_zb = 0;            // процессор: глубина каждой точки\n"; *(const char * *)tb_grow(v_lines) = tb_v4415; }
    { const char * tb_v4416 = "TB_API long long tb_zb_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4416; }
    { const char * tb_v4417 = "// 3D на видеокарте: сетка один раз ложится в память видеокарты (tb_mesh_pack), а на каждый draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v4417; }
    { const char * tb_v4418 = "// пишется только запись: 3 строки по 4 целых — поворот (камера × поворот сетки) × 2^30 и сдвиг × 4096.\n"; *(const char * *)tb_grow(v_lines) = tb_v4418; }
    { const char * tb_v4419 = "// В пачке фигур это одна особая фигура m = 3: x0 — сетка, y0 — какие грани не видны, x1 — первая запись,\n"; *(const char * *)tb_grow(v_lines) = tb_v4419; }
    { const char * tb_v4420 = "// y1 — сколько записей подряд. Углы, экран и глубину считает видеокарта (tb3.vert) целыми числами —\n"; *(const char * *)tb_grow(v_lines) = tb_v4420; }
    { const char * tb_v4421 = "// той же формулой, что процессор (tb_m3_corner): кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v4421; }
    { const char * tb_v4422 = "typedef struct { int32_t r[12]; } tb_grec;\n"; *(const char * *)tb_grow(v_lines) = tb_v4422; }
    { const char * tb_v4423 = "enum { TB_GR_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4423; }
    { const char * tb_v4424 = "TB_API tb_grec *tb_grec_p = 0;         // записи всех наборов подряд (видны видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v4424; }
    { const char * tb_v4425 = "TB_API int tb_grn = 0;                 // сколько записей в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v4425; }
    { const char * tb_v4426 = "TB_API int tb_gpu_mesh = 0;            // 1: видеокарта умеет считать сетки сама (конвейер собрался)\n"; *(const char * *)tb_grow(v_lines) = tb_v4426; }
    { const char * tb_v4427 = "TB_API int tb_mesh_gdirty = 1;         // сетки поменялись: перед рисованием залить заново\n"; *(const char * *)tb_grow(v_lines) = tb_v4427; }
    { const char * tb_v4428 = "TB_API long long tb_gbatch = 1;        // номер текущей пачки (растёт после каждой отдачи видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v4428; }
    { const char * tb_v4429 = "typedef struct { float size[2]; int32_t tbase, ntri, rbase, f, gw, gh, cull; } tb_gpc;   // постоянные шейдера сеток\n"; *(const char * *)tb_grow(v_lines) = tb_v4429; }
    { const char * tb_v4430 = "TB_API long long tb_mesh_pack(int32_t *dst);   // все сетки подряд для видеокарты (dst = 0: только размер)\n"; *(const char * *)tb_grow(v_lines) = tb_v4430; }
    { const char * tb_v4431 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc);   // постоянные для фигуры m = 3\n"; *(const char * *)tb_grow(v_lines) = tb_v4431; }
    { const char * tb_v4432 = "// TB_GSLOTS наборов памяти по кругу: пока видеокарта рисует один кадр, программа уже пишет следующий\n"; *(const char * *)tb_grow(v_lines) = tb_v4432; }
    { const char * tb_v4433 = "enum { TB_GSLOTS = 3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4433; }
    { const char * tb_v4434 = "TB_API int tb_gslot = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4434; }
    { const char * tb_v4435 = "TB_API uint32_t *tb_gpu_back = 0;      // TB_GPU_CHECK: кадр, прочитанный обратно с видеокарты\n"; *(const char * *)tb_grow(v_lines) = tb_v4435; }
    { const char * tb_v4436 = "TB_API long long tb_gpu_frames = 0, tb_gpu_bad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4436; }
    { const char * tb_v4437 = "TB_API void tb_gpu_flush(int present);   // своя у каждой системы: Metal или Vulkan\n"; *(const char * *)tb_grow(v_lines) = tb_v4437; }
    { const char * tb_v4438 = "TB_API void tb_gpu_vsync(void);          // включить или выключить ожидание экрана (tb_gpu_nosync)\n"; *(const char * *)tb_grow(v_lines) = tb_v4438; }
    { const char * tb_v4439 = "TB_API int tb_gpu_nosync = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4439; }
    { const char * tb_v4440 = "TB_API int tb_gpu_resize(int ow, int oh);   // окно поменяло размер\n"; *(const char * *)tb_grow(v_lines) = tb_v4440; }
    { const char * tb_v4441 = "// окно можно тянуть мышью, если программа спросила его размер (window_w, window_h)\n"; *(const char * *)tb_grow(v_lines) = tb_v4441; }
    { const char * tb_v4442 = "TB_API int tb_resizable = 0, tb_new_w = 0, tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4442; }
    { const char * tb_v4443 = "TB_API int tb_sharp = 0;       // window_sharp(): окно в настоящих точках экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v4443; }
    { const char * tb_v4444 = "TB_API double tb_sc = 1;        // во сколько раз точек больше (Retina — 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v4444; }
    { const char * tb_v4445 = "TB_API void tb_gfx_resizable(void);   // свои у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v4445; }
    { const char * tb_v4446 = "TB_API void tb_gfx_reimage(void);            // 1: не ждать обновления экрана (set_fps(0), TB_FPS_FREE=1)\n"; *(const char * *)tb_grow(v_lines) = tb_v4446; }
    { const char * tb_v4447 = "TB_API int tb_gpu_want(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4447; }
    { const char * tb_v4448 = "    const char *e = getenv(\"TB_GPU\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4448; }
    { const char * tb_v4449 = "    tb_gpu_check = getenv(\"TB_GPU_CHECK\") != 0 && getenv(\"TB_GPU_CHECK\")[0] == '1';\n"; *(const char * *)tb_grow(v_lines) = tb_v4449; }
    { const char * tb_v4450 = "    if (getenv(\"TB_FPS_FREE\")) tb_gpu_nosync = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4450; }
    { const char * tb_v4451 = "    return !(e && e[0] == '0');\n"; *(const char * *)tb_grow(v_lines) = tb_v4451; }
    { const char * tb_v4452 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4452; }
    { const char * tb_v4453 = "TB_API void tb_gpu_say(const char *what) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4453; }
    { const char * tb_v4454 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4454; }
    { const char * tb_v4455 = "    if ((e && e[0] == '1') || tb_gpu_check) fprintf(stderr, \"окно: рисует %s\\n\", what);\n"; *(const char * *)tb_grow(v_lines) = tb_v4455; }
    { const char * tb_v4456 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4456; }
    { const char * tb_v4457 = "TB_API void tb_gpu_report(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4457; }
    { const char * tb_v4458 = "    fprintf(stderr, \"TB_GPU_CHECK: кадров %lld, разошлось %lld\\n\", tb_gpu_frames, tb_gpu_bad);\n"; *(const char * *)tb_grow(v_lines) = tb_v4458; }
    { const char * tb_v4459 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4459; }
