    { const char * tb_v4474 = "            fprintf(stderr, \"TB_GPU_CHECK: кадр %lld: не совпало точек %lld, первая x=%lld y=%lld: видеокарта %06x, процессор %06x\\n\",\n"; *(const char * *)tb_grow(v_lines) = tb_v4474; }
    { const char * tb_v4475 = "                tb_gpu_frames, bad, first % tb_gw, first / tb_gw, tb_gpu_back[first] & 0xFFFFFF, tb_px[first] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v4475; }
    { const char * tb_v4476 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4476; }
    { const char * tb_v4477 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4477; }
    { const char * tb_v4478 = "TB_INL void tb_gpu_add(long long x0, long long y0, long long x1, long long y1, long long ox, long long oy, uint32_t c, uint32_t m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4478; }
