    { const char * tb_v4494 = "                if (g->x0 == x1) { g->x0 = (int32_t)x0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4494; }
    { const char * tb_v4495 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v4495; }
    { const char * tb_v4496 = "            if (g->x0 == x0 && g->x1 == x1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4496; }
    { const char * tb_v4497 = "                if (g->y1 == y0) { g->y1 = (int32_t)y1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4497; }
    { const char * tb_v4498 = "                if (g->y0 == y1) { g->y0 = (int32_t)y0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4498; }
    { const char * tb_v4499 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v4499; }
    { const char * tb_v4500 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4500; }
