    { const char * tb_v4504 = "TB_API void tb_gpu_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4504; }
    { const char * tb_v4505 = "    if (r < 0 || cx + r < 0 || cy + r < 0 || cx - r >= tb_gw || cy - r >= tb_gh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4505; }
    { const char * tb_v4506 = "    if (r <= 16384) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4506; }
    { const char * tb_v4507 = "        long long x0 = cx - r < 0 ? 0 : cx - r, y0 = cy - r < 0 ? 0 : cy - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v4507; }
    { const char * tb_v4508 = "        long long x1 = cx + r + 1 > tb_gw ? tb_gw : cx + r + 1, y1 = cy + r + 1 > tb_gh ? tb_gh : cy + r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4508; }
    { const char * tb_v4509 = "        tb_gpu_add(x0, y0, x1, y1, cx, cy, (uint32_t)c & 0xFFFFFF, (1u << 30) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v4509; }
    { const char * tb_v4510 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4510; }
    { const char * tb_v4511 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4511; }
    { const char * tb_v4512 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v4512; }
    { const char * tb_v4513 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v4513; }
    { const char * tb_v4514 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4514; }
    { const char * tb_v4515 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v4515; }
    { const char * tb_v4516 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v4516; }
    { const char * tb_v4517 = "        while ((i + 1) * (i + 1) <= rest) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4517; }
