    { const char * tb_v7240 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7240; }
    { const char * tb_v7241 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7241; }
    { const char * tb_v7242 = "static void tb_tri_draw_i(long long *t, long long c, const uint32_t *pl) { tb_tri_draw_x(t, c, pl, tb_gpu_on, TB_CPU_DRAW); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7242; }
    { const char * tb_v7243 = "// многоугольник с углами-дробями (3D после проекции, огромные треугольники): обрезаем рамкой\n"; *(const char * *)tb_grow(v_lines) = tb_v7243; }
    { const char * tb_v7244 = "// вокруг окна (±2048 точек, но не дальше ±8192), углы округляем, режем веером из первого угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v7244; }
    { const char * tb_v7245 = "// Общие углы округляются одинаково, поэтому соседние треугольники стыкуются без щелей\n"; *(const char * *)tb_grow(v_lines) = tb_v7245; }
    { const char * tb_v7246 = "// округление до ближайшего целого (половина — вверх); быстрее llround, одно и то же везде\n"; *(const char * *)tb_grow(v_lines) = tb_v7246; }
    { const char * tb_v7247 = "TB_INL long long tb_rnd(double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7247; }
    { const char * tb_v7248 = "    long long r = (long long)(x + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v7248; }
    { const char * tb_v7249 = "    if ((double)r > x + 0.5) r--;\n"; *(const char * *)tb_grow(v_lines) = tb_v7249; }
    { const char * tb_v7250 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v7250; }
    { const char * tb_v7251 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7251; }
    { const char * tb_v7252 = "static void tb_poly_draw(double *px, double *py, int n, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7252; }
    { const char * tb_v7253 = "    double gx0 = -2048, gy0 = -2048, gx1 = tb_gw + 2048.0, gy1 = tb_gh + 2048.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7253; }
    { const char * tb_v7254 = "    if (gx1 > 8192) gx1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v7254; }
    { const char * tb_v7255 = "    if (gy1 > 8192) gy1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v7255; }
    { const char * tb_v7256 = "    double ax[16], ay[16], bx[16], by[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v7256; }
    { const char * tb_v7257 = "    for (int i = 0; i < n; i++) { ax[i] = px[i]; ay[i] = py[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7257; }
    { const char * tb_v7258 = "    for (int side = 0; side < 4 && n > 0; side++) {   // Сазерленд — Ходжман: по одной стороне рамки\n"; *(const char * *)tb_grow(v_lines) = tb_v7258; }
    { const char * tb_v7259 = "        int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7259; }
    { const char * tb_v7260 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7260; }
    { const char * tb_v7261 = "            int j = (i + 1) % n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7261; }
    { const char * tb_v7262 = "            double vi = side == 0 ? ax[i] - gx0 : side == 1 ? gx1 - ax[i] : side == 2 ? ay[i] - gy0 : gy1 - ay[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7262; }
    { const char * tb_v7263 = "            double vj = side == 0 ? ax[j] - gx0 : side == 1 ? gx1 - ax[j] : side == 2 ? ay[j] - gy0 : gy1 - ay[j];\n"; *(const char * *)tb_grow(v_lines) = tb_v7263; }
    { const char * tb_v7264 = "            if (vi >= 0) { bx[m] = ax[i]; by[m] = ay[i]; m++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7264; }
    { const char * tb_v7265 = "            if ((vi >= 0) != (vj >= 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7265; }
    { const char * tb_v7266 = "                double k = vi / (vi - vj);\n"; *(const char * *)tb_grow(v_lines) = tb_v7266; }
    { const char * tb_v7267 = "                bx[m] = ax[i] + (ax[j] - ax[i]) * k; by[m] = ay[i] + (ay[j] - ay[i]) * k; m++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7267; }
    { const char * tb_v7268 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v7268; }
    { const char * tb_v7269 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7269; }
    { const char * tb_v7270 = "        n = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v7270; }
    { const char * tb_v7271 = "        for (int i = 0; i < n; i++) { ax[i] = bx[i]; ay[i] = by[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7271; }
    { const char * tb_v7272 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7272; }
    { const char * tb_v7273 = "    if (n < 3) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7273; }
