    { const char * tb_v7407 = "            while (nk[h] >= 0) h = (h + 1) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7407; }
    { const char * tb_v7408 = "            nk[h] = v;\n"; *(const char * *)tb_grow(v_lines) = tb_v7408; }
    { const char * tb_v7409 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7409; }
