    { const char * tb_v7411 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7411; }
    { const char * tb_v7412 = "    uint64_t h = tb_vhash(p) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7412; }
