    { const char * tb_v7416 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7416; }
    { const char * tb_v7417 = "    if (m->nv == m->capv) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7417; }
    { const char * tb_v7418 = "        m->capv = m->capv ? m->capv * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v7418; }
    { const char * tb_v7419 = "        m->v = (double *)realloc(m->v, sizeof(double) * 3 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v7419; }
