    { const char * tb_v7424 = "        if (m->nv == 0 || p[i] < m->bb[i]) m->bb[i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7424; }
    { const char * tb_v7425 = "        if (m->nv == 0 || p[i] > m->bb[3 + i]) m->bb[3 + i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7425; }
