    { const char * tb_v7562 = "// ---- 3D в целых числах: так же считает видеокарта (compiler/gpu/tb3.vert, tb.metal) ----\n"; *(const char * *)tb_grow(v_lines) = tb_v7562; }
    { const char * tb_v7563 = "// деление с округлением вниз (b > 0); через числа без знака — одинаково на любой видеокарте\n"; *(const char * *)tb_grow(v_lines) = tb_v7563; }
    { const char * tb_v7564 = "TB_INL long long tb_fdiv(long long a, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7564; }
    { const char * tb_v7565 = "    return a >= 0 ? (long long)((unsigned long long)a / (unsigned long long)b)\n"; *(const char * *)tb_grow(v_lines) = tb_v7565; }
    { const char * tb_v7566 = "                  : -(long long)(((unsigned long long)(-a) + (unsigned long long)b - 1) / (unsigned long long)b);\n"; *(const char * *)tb_grow(v_lines) = tb_v7566; }
    { const char * tb_v7567 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7567; }
    { const char * tb_v7568 = "// фокус экрана × 256 (угол обзора 60°)\n"; *(const char * *)tb_grow(v_lines) = tb_v7568; }
    { const char * tb_v7569 = "TB_INL long long tb_m3_f(void) { return tb_rnd(tb_gh / 2.0 / tan(30 * 3.14159265358979323846 / 180) * 256); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7569; }
    { const char * tb_v7570 = "// угол сетки p (× 4096) по записи r: место на экране (целые точки) и глубина D = 2^24 - 2^24 * zn / z, zn = 205 / 4096\n"; *(const char * *)tb_grow(v_lines) = tb_v7570; }
    { const char * tb_v7571 = "TB_INL void tb_m3_corner(const int32_t *r, const int32_t *p, long long f, long long *o) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7571; }
    { const char * tb_v7572 = "    long long c[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7572; }
    { const char * tb_v7573 = "    for (int k = 0; k < 3; k++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7573; }
    { const char * tb_v7574 = "        c[k] = (((long long)r[4 * k] * p[0] + (long long)r[4 * k + 1] * p[1] + (long long)r[4 * k + 2] * p[2]) >> 30) + r[4 * k + 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7574; }
    { const char * tb_v7575 = "    o[0] = ((long long)tb_gw * 128 + tb_fdiv(f * c[0], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v7575; }
    { const char * tb_v7576 = "    o[1] = ((long long)tb_gh * 128 - tb_fdiv(f * c[1], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v7576; }
    { const char * tb_v7577 = "    o[2] = 16777216 - tb_fdiv(205LL << 24, c[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7577; }
    { const char * tb_v7578 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7578; }
    { const char * tb_v7579 = "// треугольник a, b, c (x, y, D): 0 — рисовать нечего (ребром к нам или невидимая грань); иначе углы\n"; *(const char * *)tb_grow(v_lines) = tb_v7579; }
    { const char * tb_v7580 = "// по кругу «как надо» в t и плоскость глубины в pl — то же, что tb_tri3_plane, только в целых\n"; *(const char * *)tb_grow(v_lines) = tb_v7580; }
    { const char * tb_v7581 = "TB_INL int tb_m3_tri(const long long *a, const long long *b, const long long *c, int cull, long long *t, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7581; }
    { const char * tb_v7582 = "    long long area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7582; }
    { const char * tb_v7583 = "    if (area == 0 || (cull > 0 && area > 0) || (cull < 0 && area < 0)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7583; }
    { const char * tb_v7584 = "    if (area < 0) { const long long *k = b; b = c; c = k; area = -area; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7584; }
    { const char * tb_v7585 = "    long long e1x = b[0] - a[0], e1y = b[1] - a[1], e2x = c[0] - a[0], e2y = c[1] - a[1], d1 = b[2] - a[2], d2 = c[2] - a[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7585; }
    { const char * tb_v7586 = "    long long A = tb_fdiv(64 * (d1 * e2y - d2 * e1y) + area, 2 * area), B = tb_fdiv(64 * (d2 * e1x - d1 * e2x) + area, 2 * area);\n"; *(const char * *)tb_grow(v_lines) = tb_v7586; }
    { const char * tb_v7587 = "    long long C = 64 * a[2] - 2 * A * a[0] - 2 * B * a[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7587; }
    { const char * tb_v7588 = "    pl[0] = (uint32_t)A; pl[1] = (uint32_t)B; pl[2] = (uint32_t)C;\n"; *(const char * *)tb_grow(v_lines) = tb_v7588; }
    { const char * tb_v7589 = "    t[0] = a[0]; t[1] = a[1]; t[2] = b[0]; t[3] = b[1]; t[4] = c[0]; t[5] = c[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7589; }
    { const char * tb_v7590 = "    return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7590; }
    { const char * tb_v7591 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7591; }
    { const char * tb_v7592 = "// закрытая сетка (каждая сторона треугольника есть и в обратную сторону у соседа): грань, повёрнутая\n"; *(const char * *)tb_grow(v_lines) = tb_v7592; }
    { const char * tb_v7593 = "// от камеры, всегда закрыта другими гранями — и у куба снаружи, и у комнаты изнутри (грани внутрь).\n"; *(const char * *)tb_grow(v_lines) = tb_v7593; }
    { const char * tb_v7594 = "// Повёрнута от камеры = на экране по часовой стрелке (площадь < 0). 0 — рисовать все, -1 — пропускать такие\n"; *(const char * *)tb_grow(v_lines) = tb_v7594; }
    { const char * tb_v7595 = "static int tb_cmp_u64(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7595; }
    { const char * tb_v7596 = "    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v7596; }
    { const char * tb_v7597 = "    return x < y ? -1 : x > y;\n"; *(const char * *)tb_grow(v_lines) = tb_v7597; }
    { const char * tb_v7598 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7598; }
    { const char * tb_v7599 = "static int tb_mesh_cull(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7599; }
    { const char * tb_v7600 = "    if (m->cullok) return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v7600; }
    { const char * tb_v7601 = "    m->cullok = 1; m->cull = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7601; }
    { const char * tb_v7602 = "    long long ne = 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7602; }
    { const char * tb_v7603 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v7603; }
    { const char * tb_v7604 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7604; }
    { const char * tb_v7605 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7605; }
    { const char * tb_v7606 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v7606; }
    { const char * tb_v7607 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7607; }
    { const char * tb_v7608 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7608; }
    { const char * tb_v7609 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7609; }
    { const char * tb_v7610 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7610; }
    { const char * tb_v7611 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v7611; }
    { const char * tb_v7612 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7612; }
    { const char * tb_v7613 = "    for (long long i = 0; i < ne && closed; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7613; }
    { const char * tb_v7614 = "        if (i + 1 < ne && e[i] == e[i + 1]) closed = 0;   // одна сторона дважды в одну сторону\n"; *(const char * *)tb_grow(v_lines) = tb_v7614; }
    { const char * tb_v7615 = "        uint64_t back = (e[i] << 32) | (e[i] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v7615; }
    { const char * tb_v7616 = "        if ((uint32_t)e[i] == (uint32_t)(e[i] >> 32) || !bsearch(&back, e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64)) closed = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7616; }
    { const char * tb_v7617 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7617; }
    { const char * tb_v7618 = "    free(e);\n"; *(const char * *)tb_grow(v_lines) = tb_v7618; }
    { const char * tb_v7619 = "    if (closed && fabs(vol) > 1e-12) m->cull = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7619; }
    { const char * tb_v7620 = "    return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v7620; }
    { const char * tb_v7621 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7621; }
    { const char * tb_v7622 = "// сетки для видеокарты: у каждой сначала углы (x, y, z, 0), потом треугольники (номера углов, цвет)\n"; *(const char * *)tb_grow(v_lines) = tb_v7622; }
    { const char * tb_v7623 = "TB_API long long tb_mesh_pack(int32_t *dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7623; }
    { const char * tb_v7624 = "    long long at = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7624; }
    { const char * tb_v7625 = "    for (long long i = 0; i < tb_nmesh; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7625; }
    { const char * tb_v7626 = "        tb_mesh *m = &tb_meshes[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7626; }
    { const char * tb_v7627 = "        m->gv = at; m->gt = at + m->nv;\n"; *(const char * *)tb_grow(v_lines) = tb_v7627; }
    { const char * tb_v7628 = "        if (dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7628; }
    { const char * tb_v7629 = "            memcpy(dst + 4 * at, m->vi, sizeof(int32_t) * 4 * (size_t)m->nv);\n"; *(const char * *)tb_grow(v_lines) = tb_v7629; }
    { const char * tb_v7630 = "            for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7630; }
    { const char * tb_v7631 = "                int32_t *o = dst + 4 * (m->gt + t);\n"; *(const char * *)tb_grow(v_lines) = tb_v7631; }
    { const char * tb_v7632 = "                for (int k = 0; k < 3; k++) o[k] = (int32_t)(m->t[3 * t + k] + m->gv);\n"; *(const char * *)tb_grow(v_lines) = tb_v7632; }
    { const char * tb_v7633 = "                o[3] = (int32_t)(m->c[t] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v7633; }
    { const char * tb_v7634 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v7634; }
    { const char * tb_v7635 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7635; }
    { const char * tb_v7636 = "        at += m->nv + m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7636; }
    { const char * tb_v7637 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7637; }
    { const char * tb_v7638 = "    return at;\n"; *(const char * *)tb_grow(v_lines) = tb_v7638; }
    { const char * tb_v7639 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7639; }
    { const char * tb_v7640 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7640; }
    { const char * tb_v7641 = "    tb_mesh *m = &tb_meshes[g->x0];\n"; *(const char * *)tb_grow(v_lines) = tb_v7641; }
    { const char * tb_v7642 = "    pc->size[0] = (float)tb_gw; pc->size[1] = (float)tb_gh;\n"; *(const char * *)tb_grow(v_lines) = tb_v7642; }
    { const char * tb_v7643 = "    pc->tbase = (int32_t)(m->gt + g->ox); pc->ntri = g->oy; pc->rbase = (slot * TB_GR_CAP + g->x1) * 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v7643; }
    { const char * tb_v7644 = "    pc->f = (int32_t)tb_m3_f(); pc->gw = tb_gw; pc->gh = tb_gh; pc->cull = g->y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7644; }
    { const char * tb_v7645 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7645; }
    { const char * tb_v7646 = "TB_API long long *tb_3i = 0;   // углы сетки после камеры в целых: x, y, D\n"; *(const char * *)tb_grow(v_lines) = tb_v7646; }
    { const char * tb_v7647 = "TB_API long long tb_3icap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7647; }
    { const char * tb_v7648 = "// шар сетки или куска (центр в сетке, радиус) после камеры: 0 — не видно совсем (за камерой или вне экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v7648; }
    { const char * tb_v7649 = "// с запасом 2 точки), 1 — целые годятся (весь перед камерой, на экране не дальше ±8100 точек), 2 — старый путь\n"; *(const char * *)tb_grow(v_lines) = tb_v7649; }
    { const char * tb_v7650 = "static int tb_m3_test(const double *sp, double M[3][3], const double *T, double f, int big) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7650; }
    { const char * tb_v7651 = "    double cc[3], rad = sp[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7651; }
    { const char * tb_v7652 = "    for (int k = 0; k < 3; k++) cc[k] = M[k][0] * sp[0] + M[k][1] * sp[1] + M[k][2] * sp[2] + T[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v7652; }
    { const char * tb_v7653 = "    if (cc[2] + rad < 205.0 / 4096) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7653; }
    { const char * tb_v7654 = "    double hw = tb_gw / 2.0 + 2, hh = tb_gh / 2.0 + 2, lx = sqrt(f * f + hw * hw), ly = sqrt(f * f + hh * hh);\n"; *(const char * *)tb_grow(v_lines) = tb_v7654; }
    { const char * tb_v7655 = "    if ((f * cc[0] - hw * cc[2]) / lx > rad || (-f * cc[0] - hw * cc[2]) / lx > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7655; }
    { const char * tb_v7656 = "    if ((f * cc[1] - hh * cc[2]) / ly > rad || (-f * cc[1] - hh * cc[2]) / ly > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7656; }
    { const char * tb_v7657 = "    double zmin = cc[2] - rad;\n"; *(const char * *)tb_grow(v_lines) = tb_v7657; }
    { const char * tb_v7658 = "    int ok = !big && zmin >= 0.12 && fabs(T[0]) < 400000 && fabs(T[1]) < 400000 && fabs(T[2]) < 400000 &&\n"; *(const char * *)tb_grow(v_lines) = tb_v7658; }
    { const char * tb_v7659 = "             fabs(cc[0]) + rad < 400000 && fabs(cc[1]) + rad < 400000 && cc[2] + rad < 400000;\n"; *(const char * *)tb_grow(v_lines) = tb_v7659; }
    { const char * tb_v7660 = "    if (ok) ok = tb_gw / 2.0 + f * (fabs(cc[0]) + rad) / zmin < 8100 && tb_gh / 2.0 + f * (fabs(cc[1]) + rad) / zmin < 8100;\n"; *(const char * *)tb_grow(v_lines) = tb_v7660; }
    { const char * tb_v7661 = "    return ok ? 1 : 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v7661; }
    { const char * tb_v7662 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7662; }
    { const char * tb_v7663 = "// один draw_mesh в целых: запись (одна на вызов, в текущем наборе) и куски треугольников\n"; *(const char * *)tb_grow(v_lines) = tb_v7663; }
    { const char * tb_v7664 = "typedef struct { tb_mesh *m; long long id; int cull; long long ri, rbatch; tb_grec rec; } tb_m3_go;\n"; *(const char * *)tb_grow(v_lines) = tb_v7664; }
    { const char * tb_v7665 = "TB_API long long *tb_3ist = 0, tb_3igen = 0;   // какой угол уже посчитан в этом вызове (процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v7665; }
    { const char * tb_v7666 = "static void tb_m3_draw(tb_m3_go *go, long long t0, long long tn) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7666; }
    { const char * tb_v7667 = "    tb_mesh *m = go->m;\n"; *(const char * *)tb_grow(v_lines) = tb_v7667; }
    { const char * tb_v7668 = "    if (tb_gpu_on && tb_gpu_mesh) {   // видеокарта считает сама: только запись и «нарисуй треугольники t0.. из сетки»\n"; *(const char * *)tb_grow(v_lines) = tb_v7668; }
    { const char * tb_v7669 = "        if (tb_gin == TB_GI_CAP || (go->rbatch != tb_gbatch && tb_grn == TB_GR_CAP)) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7669; }
    { const char * tb_v7670 = "        if (go->rbatch != tb_gbatch) {   // запись этого вызова ещё не в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v7670; }
    { const char * tb_v7671 = "            go->ri = tb_grn++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7671; }
    { const char * tb_v7672 = "            go->rbatch = tb_gbatch;\n"; *(const char * *)tb_grow(v_lines) = tb_v7672; }
    { const char * tb_v7673 = "            tb_grec_p[tb_gslot * TB_GR_CAP + go->ri] = go->rec;\n"; *(const char * *)tb_grow(v_lines) = tb_v7673; }
    { const char * tb_v7674 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7674; }
    { const char * tb_v7675 = "        tb_ginst *g = tb_gin ? &tb_gi[tb_gin - 1] : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7675; }
    { const char * tb_v7676 = "        if (g && g->m == 3u && g->x0 == (int32_t)go->id && g->y0 == go->cull && g->ox == t0 && g->oy == tn &&\n"; *(const char * *)tb_grow(v_lines) = tb_v7676; }
    { const char * tb_v7677 = "            g->x1 + g->y1 == go->ri && (long long)(g->y1 + 1) * tn < 2000000000) g->y1++;   // та же сетка подряд: одним вызовом\n"; *(const char * *)tb_grow(v_lines) = tb_v7677; }
    { const char * tb_v7678 = "        else tb_gpu_add(go->id, go->cull, go->ri, 1, t0, tn, 0, 3u);\n"; *(const char * *)tb_grow(v_lines) = tb_v7678; }
    { const char * tb_v7679 = "        m->gused = tb_gbatch;\n"; *(const char * *)tb_grow(v_lines) = tb_v7679; }
