    { const char * tb_v7848 = "// вид стрелки мыши над окном\n"; *(const char * *)tb_grow(v_lines) = tb_v7848; }
    { const char * tb_v7849 = "TB_API void tb_set_cursor(const char *name, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7849; }
    { const char * tb_v7850 = "    static const char *names[] = { \"arrow\", \"hand\", \"text\", \"move\", \"resize_x\", \"resize_y\", \"wait\", \"none\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v7850; }
