    { const char * tb_v7857 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v7857; }
    { const char * tb_v7858 = "// ---------- для файла .ll (TB_LL): библиотека видна снаружи через tb_x_* ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7858; }
    { const char * tb_v7859 = "// Сама библиотека — static: так её лучше встраивать. Эти обёртки — её «дверь» для LLVM.\n"; *(const char * *)tb_grow(v_lines) = tb_v7859; }
    { const char * tb_v7860 = "// Без clang (llvm-link + opt + llc) библиотека заранее лежит в файле .bc, а программа\n"; *(const char * *)tb_grow(v_lines) = tb_v7860; }
    { const char * tb_v7861 = "// целиком в .ll: показ значений, конструкторы и main тоже пишутся в .ll.\n"; *(const char * *)tb_grow(v_lines) = tb_v7861; }
    { const char * tb_v7862 = "#if defined(TB_SND) && !defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v7862; }
    { const char * tb_v7863 = "// ---------- звук: load_sound, play_sound, play_sound_at, listener ... ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7863; }
    { const char * tb_v7864 = "// Микшер: 48 000 кадров в секунду, стерео, числа float, блоки по 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v7864; }
    { const char * tb_v7865 = "// Голос = звук + громкость + высота (+ место в мире для 3D). В 3D: громкость падает с\n"; *(const char * *)tb_grow(v_lines) = tb_v7865; }
    { const char * tb_v7866 = "// расстоянием, сторона (лево/право) слышна по громкости И по задержке между ушами (как у\n"; *(const char * *)tb_grow(v_lines) = tb_v7866; }
    { const char * tb_v7867 = "// настоящей головы), дальнее ухо и звук сзади глуше (тень головы), воздух глушит высокие\n"; *(const char * *)tb_grow(v_lines) = tb_v7867; }
    { const char * tb_v7868 = "// у далёких звуков, а движение даёт эффект Доплера. Громкость и место меняются плавно\n"; *(const char * *)tb_grow(v_lines) = tb_v7868; }
    { const char * tb_v7869 = "// внутри блока — без щелчков. На выходе ограничитель: сколько звуков ни играй, не трещит.\n"; *(const char * *)tb_grow(v_lines) = tb_v7869; }
    { const char * tb_v7870 = "// Куда идёт звук: Mac — AudioQueue, Linux — ALSA, Windows — waveOut (библиотеки грузятся при\n"; *(const char * *)tb_grow(v_lines) = tb_v7870; }
    { const char * tb_v7871 = "// запуске; нет их — тишина, программа работает). TB_SOUND_FILE=путь.wav — в файл (проверки),\n"; *(const char * *)tb_grow(v_lines) = tb_v7871; }
    { const char * tb_v7872 = "// TB_SOUND=0 — никуда (время идёт, звуки «играют» молча).\n"; *(const char * *)tb_grow(v_lines) = tb_v7872; }
    { const char * tb_v7873 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v7873; }
    { const char * tb_v7874 = "#include <dlfcn.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v7874; }
    { const char * tb_v7875 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v7875; }
    { const char * tb_v7876 = "#define TB_SR 48000\n"; *(const char * *)tb_grow(v_lines) = tb_v7876; }
    { const char * tb_v7877 = "#define TB_SBLOCK 480\n"; *(const char * *)tb_grow(v_lines) = tb_v7877; }
    { const char * tb_v7878 = "#define TB_NVOICE 64\n"; *(const char * *)tb_grow(v_lines) = tb_v7878; }
    { const char * tb_v7879 = "typedef struct { float *d; long long n; int ch; double rate; int temp; } tb_snd;\n"; *(const char * *)tb_grow(v_lines) = tb_v7879; }
    { const char * tb_v7880 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v7880; }
    { const char * tb_v7881 = "    int on, gen, snd, loop, is3d, fresh, stop;\n"; *(const char * *)tb_grow(v_lines) = tb_v7881; }
    { const char * tb_v7882 = "    double pos, pitch, vol, x, y, z;\n"; *(const char * *)tb_grow(v_lines) = tb_v7882; }
    { const char * tb_v7883 = "    float gl, gr, lpl, lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v7883; }
    { const char * tb_v7884 = "    double dl, dr, lastd, dop;\n"; *(const char * *)tb_grow(v_lines) = tb_v7884; }
    { const char * tb_v7885 = "} tb_voice;\n"; *(const char * *)tb_grow(v_lines) = tb_v7885; }
    { const char * tb_v7886 = "static tb_snd *tb_snds;\n"; *(const char * *)tb_grow(v_lines) = tb_v7886; }
    { const char * tb_v7887 = "static int tb_nsnd;\n"; *(const char * *)tb_grow(v_lines) = tb_v7887; }
    { const char * tb_v7888 = "static tb_voice tb_voices[TB_NVOICE];\n"; *(const char * *)tb_grow(v_lines) = tb_v7888; }
    { const char * tb_v7889 = "static pthread_mutex_t tb_slock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v7889; }
    { const char * tb_v7890 = "// слушатель: где он, вектор «вправо», вектор «вперёд» (как у camera)\n"; *(const char * *)tb_grow(v_lines) = tb_v7890; }
    { const char * tb_v7891 = "static double tb_lis[9] = { 0, 0, 0, 1, 0, 0, 0, 0, 1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v7891; }
    { const char * tb_v7892 = "static double tb_master = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7892; }
    { const char * tb_v7893 = "static float tb_mg = 1, tb_lim = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7893; }
    { const char * tb_v7894 = "static int tb_snd_started;\n"; *(const char * *)tb_grow(v_lines) = tb_v7894; }
    { const char * tb_v7895 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v7895; }
    { const char * tb_v7896 = "TB_INL float tb_sget(const tb_snd *s, long long i, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7896; }
    { const char * tb_v7897 = "    if (i < 0 || i >= s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7897; }
    { const char * tb_v7898 = "        if (!loop || s->n == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7898; }
    { const char * tb_v7899 = "        i %= s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7899; }
    { const char * tb_v7900 = "        if (i < 0) i += s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7900; }
    { const char * tb_v7901 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7901; }
    { const char * tb_v7902 = "    return s->d[i * s->ch + (c < s->ch ? c : 0)];\n"; *(const char * *)tb_grow(v_lines) = tb_v7902; }
    { const char * tb_v7903 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7903; }
    { const char * tb_v7904 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v7904; }
    { const char * tb_v7905 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7905; }
    { const char * tb_v7906 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v7906; }
    { const char * tb_v7907 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v7907; }
    { const char * tb_v7908 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v7908; }
    { const char * tb_v7909 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v7909; }
    { const char * tb_v7910 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v7910; }
    { const char * tb_v7911 = "    return ((c3 * t + c2) * t + c1) * t + b;\n"; *(const char * *)tb_grow(v_lines) = tb_v7911; }
    { const char * tb_v7912 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7912; }
    { const char * tb_v7913 = "TB_INL float tb_smono(const tb_snd *s, double p, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7913; }
    { const char * tb_v7914 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v7914; }
    { const char * tb_v7915 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v7915; }
    { const char * tb_v7916 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7916; }
    { const char * tb_v7917 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v7917; }
    { const char * tb_v7918 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7918; }
    { const char * tb_v7919 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7919; }
    { const char * tb_v7920 = "    tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v7920; }
    { const char * tb_v7921 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7921; }
    { const char * tb_v7922 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7922; }
    { const char * tb_v7923 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v7923; }
    { const char * tb_v7924 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7924; }
    { const char * tb_v7925 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7925; }
    { const char * tb_v7926 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v7926; }
    { const char * tb_v7927 = "    double side = 0, front = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7927; }
    { const char * tb_v7928 = "    if (d > 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7928; }
    { const char * tb_v7929 = "        side = (dx * tb_lis[3] + dy * tb_lis[4] + dz * tb_lis[5]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7929; }
    { const char * tb_v7930 = "        front = (dx * tb_lis[6] + dy * tb_lis[7] + dz * tb_lis[8]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7930; }
    { const char * tb_v7931 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7931; }
    { const char * tb_v7932 = "    if (d < 0.25) { side *= d / 0.25; front = 1; }   // звук «в голове» — по центру\n"; *(const char * *)tb_grow(v_lines) = tb_v7932; }
    { const char * tb_v7933 = "    double g = d <= 1 ? 1 : 1 / d;                    // громкость падает с расстоянием\n"; *(const char * *)tb_grow(v_lines) = tb_v7933; }
    { const char * tb_v7934 = "    double a = (side + 1) * 0.7853981633974483;      // стороны с равной мощностью\n"; *(const char * *)tb_grow(v_lines) = tb_v7934; }
    { const char * tb_v7935 = "    *tl = (float)(v->vol * g * cos(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v7935; }
    { const char * tb_v7936 = "    *tr = (float)(v->vol * g * sin(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v7936; }
    { const char * tb_v7937 = "    double itd = 0.00066 * TB_SR * fabs(side);        // до 0,66 мс между ушами\n"; *(const char * *)tb_grow(v_lines) = tb_v7937; }
    { const char * tb_v7938 = "    *tdl = side > 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7938; }
    { const char * tb_v7939 = "    *tdr = side < 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7939; }
    { const char * tb_v7940 = "    double fc = 20000 / (1 + d * 0.03);               // воздух: далёкие звуки глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v7940; }
    { const char * tb_v7941 = "    if (front < 0) fc *= 1 - 0.35 * -front;           // сзади глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v7941; }
    { const char * tb_v7942 = "    double fs = fc * (1 - 0.65 * fabs(side));         // дальнее ухо в тени головы\n"; *(const char * *)tb_grow(v_lines) = tb_v7942; }
    { const char * tb_v7943 = "    double cl = side > 0 ? fs : fc, cr = side < 0 ? fs : fc;\n"; *(const char * *)tb_grow(v_lines) = tb_v7943; }
    { const char * tb_v7944 = "    *fl = (float)(1 - exp(-6.283185307179586 * cl / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v7944; }
    { const char * tb_v7945 = "    *fr = (float)(1 - exp(-6.283185307179586 * cr / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v7945; }
    { const char * tb_v7946 = "    // Доплер: как быстро звук приближается (расстояние за блок 10 мс), звук летит 343 ед/с\n"; *(const char * *)tb_grow(v_lines) = tb_v7946; }
