    { const char * tb_v8199 = "// WAV: PCM 8/16/24/32 бита или float 32; моно или стерео (больше каналов — берём первые два)\n"; *(const char * *)tb_grow(v_lines) = tb_v8199; }
    { const char * tb_v8200 = "TB_API long long tb_load_sound(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8200; }
    { const char * tb_v8201 = "    FILE *f = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8201; }
    { const char * tb_v8202 = "    if (!f) { tb_err = \"нет такого файла звука\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8202; }
    { const char * tb_v8203 = "    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v8203; }
    { const char * tb_v8204 = "    unsigned char *b = sz > 0 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8204; }
    { const char * tb_v8205 = "    if (!b || fread(b, 1, (size_t)sz, f) != (size_t)sz) { fclose(f); free(b); tb_err = \"не могу прочитать файл звука\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8205; }
    { const char * tb_v8206 = "    fclose(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v8206; }
    { const char * tb_v8207 = "    if (sz < 12 || memcmp(b, \"RIFF\", 4) != 0 || memcmp(b + 8, \"WAVE\", 4) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8207; }
    { const char * tb_v8208 = "        tb_err = sz >= 4 && memcmp(b, \"OggS\", 4) == 0 ? \"OGG пока не умею: сохрани звук как WAV\" : \"это не WAV-файл\";\n"; *(const char * *)tb_grow(v_lines) = tb_v8208; }
    { const char * tb_v8209 = "        free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v8209; }
    { const char * tb_v8210 = "        return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8210; }
    { const char * tb_v8211 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8211; }
    { const char * tb_v8212 = "    uint32_t tag = 0, ch = 0, rate = 0, bits = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8212; }
    { const char * tb_v8213 = "    const unsigned char *data = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8213; }
    { const char * tb_v8214 = "    uint32_t dlen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8214; }
    { const char * tb_v8215 = "    long p = 12;\n"; *(const char * *)tb_grow(v_lines) = tb_v8215; }
    { const char * tb_v8216 = "    while (p + 8 <= sz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8216; }
    { const char * tb_v8217 = "        uint32_t n = tb_le32(b + p + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8217; }
