    { const char * tb_v8227 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8227; }
    { const char * tb_v8228 = "    int okf = (tag == 1 && (bits == 8 || bits == 16 || bits == 24 || bits == 32)) || (tag == 3 && (bits == 32 || bits == 64));\n"; *(const char * *)tb_grow(v_lines) = tb_v8228; }
    { const char * tb_v8229 = "    if (!data || !okf || ch == 0 || rate == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8229; }
    { const char * tb_v8230 = "        free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v8230; }
    { const char * tb_v8231 = "        tb_err = !data ? \"в WAV нет звука (нет куска data)\" : \"такой WAV не умею: нужен PCM 8/16/24/32 бита или float\";\n"; *(const char * *)tb_grow(v_lines) = tb_v8231; }
    { const char * tb_v8232 = "        return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8232; }
